{"command":"python3 -c "
import json
ts=json.load(open('/tmp/kb_tasks.json'))
ts = ts if isinstance(ts,list) else ts.get('tasks',ts)
import re
for t in ts:
    blob=((t.get('title') or '')+' '+(t.get('goal') or '')).lower()
    if re.search(r'canary|flak|overlay|quarantine|retry|windowms|forward.*opt|runner/version', blob):
        print(t.get('id'),'|',t.get('status'),'|',(t.get('title') or '')[:80])
"","description":"Grep all tickets for overlapping goals"}

